sys_script_include.script:
var NowflixUtils = Class.create();
NowflixUtils.prototype = {
    initialize: function() {},
	refQualMedia: function() {
		let grMedia = new GlideRecord("x_1974925_nowflix_media"), mediaUnlist = [];
		grMedia.addQuery("state", "3");
		grMedia.query();

		while(grMedia.next()){
			let grReview = new GlideRecord("x_1974925_nowflix_review");
			//grReview.addEncodedQuery("state!=4^opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe");
			grReview.addQuery("opened_by", gs.getUserID());
			grReview.addQuery("media", grMedia.sys_id);
			grReview.addQuery("state","!=","4");
			grReview.query();

			if(!grReview.next()){
				mediaUnlist.push(grMedia.getUniqueValue());
				//filmes que não deveriam ser exibidos.
			}
		}
		return "sys_idIN" + mediaUnlist.join(",");
	},

    type: 'NowflixUtils'
};
